windowclass.script:
function onInit()
	if WindowTabManager then
		local tTabs = WindowTabManager.getTabsFromWindow(self);

		local sTabRes = "tab_cohorts";
		if Interface.getVersion() < 4 then
			sTabRes = "tab_cohorts_icon";
		end

		WindowTabManager.registerTab('charsheet', {
			sName = 'cohorts', 
			sTabRes = sTabRes,
			sClass = 'charsheet_cohorts', 
			sInsertBefore = 'notes'
		})

		WindowTabManager.updateTabDisplay(self, tTabs);
	end

	if super and super.onInit then
		super.onInit();
	end
end

tabs_charsheet.script:
function onInit()
	if not WindowTabManager then
		local sTabRes = "tab_cohorts";
		if Interface.getVersion() < 4 then
			sTabRes = "tab_cohorts_icon";
		end

		local bLogsFound = false;
		if tab and type(tab) == "table" then
			for index,tabInfo in ipairs(tab) do
				if (type(tabInfo) == "table") and (tabInfo.subwindow[1] == "logs") then
					tabInfo.icon[1] = sTabRes;
					bLogsFound = true;
				end
			end

			if not bLogsFound then
				local tNewTab = {
					icon = { sTabRes },
					subwindow = { "logs" }
				};
				table.insert(tab, tNewTab);
			end
		end
	end

	if super and super.onInit then
		super.onInit();
	end
end
